        ],
    )
    message = getattr(result, "llm", result)
    return str(getattr(message, "raw_text", "") or getattr(message, "text", ""))


async def _actor_turn(role: str, question: str, transcript: list[str]) -> str:
    search_payload = await search_web(question + " " + role, provider="parallel", num=2)
    observations: list[str] = []
    for row in _search_rows(search_payload)[:2]:
        url = str(getattr(row, "link", ""))
